// Handle both body.user_id and direct user_id
const payload = $json.body || $json;
let userEmail = (payload.user_email || '').trim().toLowerCase();
if (userEmail) return { userEmail };

// If not provided, we'll look it up in the next Postgres node using user_id
const userId = payload.user_id;
if (!userId) throw new Error('user_id is required in webhook body');
return { userId, userEmail: null };

const extractResult = $('Extract User Email').item.json;
let userEmail = extractResult.userEmail;

// If no email from extract node, look it up from previous query
if (!userEmail) {
  const lookupResult = $input.item.json;
  userEmail = (lookupResult.email || '').trim().toLowerCase();
}

if (!userEmail) throw new Error('Could not determine user_email');
return { userEmail };

const triggerData = $('Manual Proposal Trigger').first().json;
const trigger = triggerData.body || triggerData;
const pricingRows = $input.all().map(i => i.json);

const rawId = (trigger.request_id || '').toString().trim();
const meetingId = rawId.length > 0 ? rawId : `manual-${Date.now()}`;

const validDays = parseInt(trigger.valid_days) || 30;
const validUntil = new Date();
validUntil.setDate(validUntil.getDate() + validDays);
const formatDate = (d) => d.toISOString().split('T')[0];

let bodyHtml = (trigger.proposal_body || '').trim();
if (!/<[a-z][\s\S]*>/i.test(bodyHtml)) {
  bodyHtml = bodyHtml
    .split(/\n{2,}/)
    .map(para => `<p>${para.replace(/\n/g, '<br>')}</p>`)
    .join('');
}

const quotedPrice = Number(trigger.quoted_price);
if (!Number.isFinite(quotedPrice)) {
  throw new Error(`quoted_price missing or invalid in webhook body: ${JSON.stringify(trigger.quoted_price)}`);
}

return {
  meeting_id: meetingId,
  lead_email: trigger.lead_email,
  overview: `Manual proposal drafted for ${trigger.lead_name}`,
  requirements: {
    budget_signal: null,
    timeline: null,
    key_requirements: [],
    pain_points: [],
    objections_raised: [],
    competitors_mentioned: [],
    decision_makers: []
  },
  pricing_catalog_json: pricingRows,
  proposal: {
    subject: trigger.proposal_subject,
    body_html: bodyHtml,
    package_selected: (trigger.proposal_template || '').trim(),
    quoted_price: quotedPrice,
    valid_until: formatDate(validUntil)
  }
};
